import { next } from '@vercel/functions';

// Runs on every request except Vercel's own endpoints, so the videos under
// /watch are gated too, not just the page. Routing Middleware runs before the
// cache, which is what makes that possible on a static deployment.
export const config = {
  matcher: ['/((?!_vercel/).*)'],
};

// The Indeed Flex wordmark, inlined rather than imported so this file has no
// module resolution to get wrong, and the login page needs no ungated asset.
const WORDMARK =
  'data:image/png;base64,';

const COOKIE = 'flex_pb';
const TOKEN_MESSAGE = 'flex-playbook-v1';
const THIRTY_DAYS = 60 * 60 * 24 * 30;

// The cookie holds an HMAC derived from the password, never the password
// itself. Changing SITE_PASSWORD therefore invalidates every existing
// session without any stored state.
async function sessionToken(password: string) {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw',
    enc.encode(password),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  );
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(TOKEN_MESSAGE));
  return Array.from(new Uint8Array(sig))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

// Length-independent comparison, so a wrong guess does not leak how much of
// the password was right.
function matches(a: string, b: string) {
  const len = Math.max(a.length, b.length);
  let diff = a.length ^ b.length;
  for (let i = 0; i < len; i += 1) {
    diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  }
  return diff === 0;
}

function loginPage(wrong: boolean) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex, nofollow">
<title>Revenue second brain</title>
<style>
  :root { --ink:#001435; --pink:#DD00A9; --wash:#F7F5F7; --line:#F0EDEF; --muted:rgba(0,20,53,.68); }
  * { box-sizing:border-box; }
  body {
    margin:0; min-height:100vh; display:grid; place-items:center; padding:24px;
    background:var(--wash); color:var(--ink);
    font-family:'Indeed Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;
  }
  .card {
    width:100%; max-width:420px; background:#fff; border:1px solid var(--line);
    border-radius:20px; padding:36px 32px 32px; box-shadow:0 18px 40px rgba(0,20,53,.07);
  }
  .mark { height:20px; display:block; margin:0 0 26px; }
  .eye { font-size:13px; font-weight:700; color:var(--pink); margin:0 0 10px; letter-spacing:.02em; }
  h1 { font-size:25px; font-weight:500; letter-spacing:-.02em; line-height:1.2; margin:0 0 8px; }
  h1 em { font-family:Georgia,'Times New Roman',serif; font-style:italic; color:var(--pink); }
  p.lede { font-size:15px; line-height:1.5; color:var(--muted); margin:0 0 24px; }
  label { display:block; font-size:13px; font-weight:700; margin:0 0 7px; }
  input {
    width:100%; font:inherit; font-size:16px; padding:13px 15px;
    border:1px solid var(--line); border-radius:12px; background:var(--wash); color:var(--ink);
  }
  input:focus { outline:2px solid var(--pink); outline-offset:1px; background:#fff; }
  button {
    width:100%; margin-top:14px; font:inherit; font-size:15px; font-weight:700;
    padding:13px 16px; border:0; border-radius:999px;
    background:var(--ink); color:#fff; cursor:pointer;
  }
  button:hover { background:#002a6b; }
  .err {
    font-size:14px; font-weight:700; color:var(--pink);
    margin:14px 0 0; padding:11px 13px;
    background:rgba(221,0,169,.07); border-radius:10px;
  }
  .foot { font-size:13px; color:var(--muted); margin:22px 0 0; }
</style>
</head>
<body>
  <main class="card">
    <img class="mark" src="${WORDMARK}" alt="Indeed Flex">
    <p class="eye">Revenue second brain</p>
    <h1>This page is <em>internal</em></h1>
    <p class="lede">Enter the team password to open the playbook.</p>
    <form method="post" autocomplete="on">
      <label for="password">Password</label>
      <input id="password" name="password" type="password" autocomplete="current-password"
             autofocus required aria-describedby="${wrong ? 'err' : 'foot'}">
      <button type="submit">Open the playbook</button>
    </form>
    ${wrong ? '<p class="err" id="err" role="alert">That password is not right. Try again.</p>' : ''}
    <p class="foot" id="foot">Ask in the team channel if you do not have it.</p>
  </main>
</body>
</html>`;
}

const HTML_HEADERS = {
  'Content-Type': 'text/html; charset=utf-8',
  'Cache-Control': 'no-store',
  'X-Robots-Tag': 'noindex, nofollow',
};

export default async function middleware(request: Request) {
  const expected = process.env.SITE_PASSWORD;

  // Fail closed. An unset password must not quietly leave the site open,
  // because that is indistinguishable from a working gate.
  if (!expected) {
    return new Response(
      'SITE_PASSWORD is not set on this deployment, so the site is closed.',
      { status: 503, headers: { 'Cache-Control': 'no-store' } },
    );
  }

  const url = new URL(request.url);
  const good = await sessionToken(expected);

  // the login form posts back to whatever path the visitor was on
  if (request.method === 'POST') {
    let submitted = '';
    try {
      submitted = String((await request.formData()).get('password') || '');
    } catch {
      submitted = '';
    }
    if (matches(submitted, expected)) {
      const secure = url.protocol === 'https:' ? '; Secure' : '';
      return new Response(null, {
        status: 303,
        headers: {
          Location: url.pathname + url.search,
          'Set-Cookie': `${COOKIE}=${good}; Path=/; HttpOnly${secure}; SameSite=Lax; Max-Age=${THIRTY_DAYS}`,
          'Cache-Control': 'no-store',
        },
      });
    }
    return new Response(loginPage(true), { status: 401, headers: HTML_HEADERS });
  }

  const cookies = (request.headers.get('cookie') || '').split(/;\s*/);
  if (cookies.includes(`${COOKIE}=${good}`)) {
    return next();
  }

  // Only a page navigation should get the login screen. A video or an image
  // asking for itself gets a plain 401, not a mouthful of HTML.
  const wantsHtml = (request.headers.get('accept') || '').includes('text/html');
  if (!wantsHtml) {
    return new Response('Unauthorized', {
      status: 401,
      headers: { 'Cache-Control': 'no-store' },
    });
  }

  return new Response(loginPage(false), { status: 401, headers: HTML_HEADERS });
}
